const msg = $('Message Received').item.json.message;

if (!msg || !msg.text) {
  throw new Error('Empty or non-text message received');
}

const text = String(msg.text).trim();
if (text.length === 0) {
  throw new Error('Message text is empty after trimming');
}
if (text.length > 2000) {
  throw new Error('Message exceeds maximum allowed length');
}

return {
  json: {
    chatId: String(msg.chat.id),
    query: text,
    username: msg.from.username || msg.from.first_name || 'unknown',
    correlationId: `${msg.chat.id}-${msg.date}`
  }
};

const rawRows = $input.all().map(i => i.json);
const validRows = rawRows.filter(r => r && r.role && r.content);
const chronological = validRows.reverse();

const formattedHistory = chronological
  .map(r => `${r.role.toUpperCase()}: ${r.content}`)
  .join('\n');

return [{
  json: {
    chatId: $('validate and normalize the query').item.json.chatId,
    query: $('validate and normalize the query').item.json.query,
    username: $('validate and normalize the query').item.json.username,
    correlationId: $('validate and normalize the query').item.json.correlationId,
    chatHistory: formattedHistory || '(no previous messages)'
  }
}];

