{
  "type": "object",
  "properties": {
    "schema_version": {
      "type": "string"
    },
    "answer": {
      "type": "string"
    },
    "needs_human_escalation": {
      "type": "boolean"
    },
    "category": {
      "type": "string",
      "enum": [
        "billing",
        "technical",
        "order_status",
        "general",
        "complaint"
      ]
    },
    "used_order_id": {
      "type": [
        "string",
        "null"
      ],
      "description": "The exact order_id passed to the order lookup tool, if it was called. Null if the tool was not used."
    },
    "used_email": {
      "type": [
        "string",
        "null"
      ],
      "description": "The exact email passed to the order lookup tool, if it was called. Null if the tool was not used."
    },
    "escalation_already_open": {
      "type": "boolean",
      "description": "True if Check Existing Follow-Up Ticket found an already-open ticket for this chat. Used to prevent duplicate ticket creation."
    }
  },
  "required": [
    "answer",
    "needs_human_escalation",
    "category",
    "escalation_already_open"
  ]
}

