const output = $input.item.json.output;

if (!output.schema_version) output.schema_version = "1.0";

const validCategories = ['billing', 'technical', 'order_status', 'general', 'complaint'];
if (!validCategories.includes(output.category)) {
  output.category = 'general';
}

return { json: output };

const agentOutput = $('Post-process Agent Output').first().json;
const orderRows = $('Lookup Order for Critic').all()
  .map(i => i.json)
  .filter(r => r && !r.error && r.order_id);

const hasEvidence = orderRows.length === 1;
const orderEvidence = hasEvidence
  ? JSON.stringify(orderRows[0])
  : orderRows.length > 1
    ? 'Multiple orders matched this email; cannot confirm which specific order the customer means.'
    : 'No order was mentioned, or no matching order/email combination was found.';

return {
  json: {
    query: $('validate and normalize the query').first().json.query,
    draftAnswer: agentOutput.answer,
    orderEvidence: orderEvidence,
    needsEscalation: agentOutput.needs_human_escalation || false,
    escalationAlreadyOpen: agentOutput.escalation_already_open || false
  }
};

const agentOutput = $('Post-process Agent Output').first().json;
const query = $('validate and normalize the query').first().json.query  || '';

// Primary: trust what the Brain says it actually used with the order lookup tool
let extractedOrderId = agentOutput.used_order_id || null;
let extractedEmail = agentOutput.used_email || null;

// Fallback: only re-derive from raw text if the Brain reported nothing,
// e.g. it should have used the tool but didn't
if (!extractedOrderId) {
  const orderMatch = query.match(/ORD-?\d+/i);
  extractedOrderId = orderMatch ? orderMatch[0].toUpperCase().replace(/\s+/g, '') : null;
}
if (!extractedEmail) {
  const emailMatch = query.match(/[\w.-]+@[\w.-]+\.\w+/i);
  extractedEmail = emailMatch ? emailMatch[0] : null;
}

return {
  json: {
    extractedOrderId,
    extractedEmail
  }
};

const RATE_LIMIT = 2;           // max messages allowed per window
const WINDOW_SECONDS = 60;      // sliding window length in seconds

const chatId = String($('Message Received').first().json.message.chat.id);
const rows = $input.all().map(i => i.json).filter(j => j && Object.keys(j).length > 0);
const existing = rows.length > 0 ? rows[0] : null;

const now = Date.now();
const windowMs = WINDOW_SECONDS * 1000;

let windowStart = existing ? new Date(existing.window_start).getTime() : now;
let count = existing ? Number(existing.request_count) : 0;

const windowExpired = !existing || (now - windowStart) > windowMs;

if (windowExpired) {
  windowStart = now;
  count = 1;
} else {
  count += 1;
}

const limited = !windowExpired && count > RATE_LIMIT;

return [{
  json: {
    chatId,
    hasExisting: !!existing,
    windowStartIso: new Date(windowStart).toISOString(),
    requestCount: count,
    limited,
    retryAfterSeconds: limited ? Math.max(1, Math.ceil((windowStart + windowMs - now) / 1000)) : 0
  }
}];

const items = $input.all();
const updated = items.length > 0 && items[0].json && Object.keys(items[0].json).length > 0;

return [{
  json: {
    updated,
    ticketId: $('Parse Slack Command').item.json.ticketId,
    resolvedBy: $('Parse Slack Command').item.json.resolvedBy,
    responseUrl: $('Parse Slack Command').item.json.responseUrl
  }
}];

const body = $json.body || {};
const ticketId = (body.text || '').trim();

if (!ticketId) {
  throw new Error('Usage: /resolve-ticket <ticket_id>');
}

return [{
  json: {
    ticketId,
    resolvedBy: body.user_name || body.user_id || 'unknown',
    responseUrl: body.response_url
  }
}];
